void calculate_proportions(uint16_t proportion, uint16_t max_proportion, uint16_t* min_proportion, uint16_t* max_proportion) { uint16_t proportions = min_proportion ? *min_proportion : 0; uint16_t max_proportions = max_proportion ? *max_proportion : 0; if (proportion <= 0 || proportion < max_proportion || (proportions <= 0 && max_proportions <= 0)) { max_proportions = max_proportion * proportions / proportion; } else if (max_proportion > 0) { proportions = proportion * max_proportions / max_proportion; } if (min_proportion) { *min_proportion = proportions; } if (max_proportion) { *max_proportions = max_proportions; } }